(function(){
'use strict';

var NS = 'ilmx-sj-';
var COPY_DATA = [{"arabic": "جُمُعَة مُبَارَكَة", "rumi": "Jumu'ah Mubarakah", "terjemah": "Semoga hari Jumaat yang diberkati", "whatsapp": "جُمُعَة مُبَارَكَة\\n\\nJumu'ah Mubarakah\\n\\nSemoga hari Jumaat yang diberkati\\n\\nSumber: https://ilmualam.com/p/salam-jumaat-ucapan-maksud-hukum.html"}, {"arabic": "تَقَبَّلَ اللَّهُ مِنَّا وَمِنْكُمْ", "rumi": "Taqabbalallahu minna wa minkum", "terjemah": "Semoga Allah menerima amalan kita dan kamu", "whatsapp": "تَقَبَّلَ اللَّهُ مِنَّا وَمِنْكُمْ\\n\\nTaqabbalallahu minna wa minkum\\n\\nSemoga Allah menerima amalan kita dan kamu\\n\\nSumber: https://ilmualam.com/p/salam-jumaat-ucapan-maksud-hukum.html"}, {"arabic": "بَارَكَ اللَّهُ فِيكَ", "rumi": "Barakallahu fik", "terjemah": "Semoga Allah memberkatimu", "whatsapp": "بَارَكَ اللَّهُ فِيكَ\\n\\nBarakallahu fik\\n\\nSemoga Allah memberkatimu\\n\\nSumber: https://ilmualam.com/p/salam-jumaat-ucapan-maksud-hukum.html"}, {"arabic": "جَعَلَنَا اللَّهُ وَإِيَّاكُمْ مِنْ عُتَقَاءِ يَوْمِ الْجُمُعَةِ", "rumi": "Ja'alanallahu wa iyyakum min 'utaqa'i yawmil jumu'ah", "terjemah": "Semoga Allah menjadikan kita dan kamu tergolong hamba yang dibebaskan dari api neraka pada hari Jumaat", "whatsapp": "جَعَلَنَا اللَّهُ وَإِيَّاكُمْ مِنْ عُتَقَاءِ يَوْمِ الْجُمُعَةِ\\n\\nJa'alanallahu wa iyyakum min 'utaqa'i yawmil jumu'ah\\n\\nSemoga Allah menjadikan kita dan kamu tergolong hamba yang dibebaskan dari api neraka pada hari Jumaat\\n\\nSumber: https://ilmualam.com/p/salam-jumaat-ucapan-maksud-hukum.html"}, {"arabic": "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ", "rumi": "Allahumma solli 'ala Muhammad wa 'ala aali Muhammad", "terjemah": "Ya Allah, limpahkanlah selawat ke atas Nabi Muhammad dan keluarganya", "whatsapp": "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ\\n\\nAllahumma solli 'ala Muhammad wa 'ala aali Muhammad\\n\\nYa Allah, limpahkanlah selawat ke atas Nabi Muhammad dan keluarganya\\n\\nSumber: https://ilmualam.com/p/salam-jumaat-ucapan-maksud-hukum.html"}];

var ILMX_B = "";
function ilmxDecode(b64){
  try{
    var rev = b64.split('').reverse().join('');
    var json = decodeURIComponent(escape(atob(rev)));
    return JSON.parse(json);
  }catch(e){ return {}; }
}
var GREETINGS = ilmxDecode(ILMX_B);

var CAT_LABELS = {
  ringkas:"Ringkas", formal:"Formal", korporat:"Korporat", whatsapp:"WhatsApp",
  facebook:"Facebook", instagram:"Instagram", telegram:"Telegram", guru:"Guru",
  keluarga:"Keluarga", pasangan:"Pasangan", sahabat:"Sahabat", perniagaan:"Perniagaan",
  motivasi:"Motivasi", islamik:"Islamik", english:"English", arabic:"Arab + Rumi", emoji:"Emoji"
};
var CAT_ORDER = ["ringkas","formal","korporat","whatsapp","facebook","instagram","telegram","guru","keluarga","pasangan","sahabat","perniagaan","motivasi","islamik","english","arabic","emoji"];

var activeCat = "ringkas";
var lastText = "";
var lastShareText = "";

function $(sel, root){ return (root||document).querySelector(sel); }
function $all(sel, root){ return Array.prototype.slice.call((root||document).querySelectorAll(sel)); }
function pick(arr){ return arr[Math.floor(Math.random()*arr.length)]; }

function toast(msg){
  var t = $('.'+NS+'toast');
  if(!t) return;
  t.textContent = msg;
  t.classList.add(NS+'show');
  setTimeout(function(){ t.classList.remove(NS+'show'); }, 1800);
}

function copyText(text, okMsg){
  if(!text){ toast('Jana ucapan dahulu'); return; }
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(function(){ toast(okMsg||'Disalin!'); })['catch'](function(){ fallbackCopy(text, okMsg); });
  } else { fallbackCopy(text, okMsg); }
}
function fallbackCopy(text, okMsg){
  try{
    var ta = document.createElement('textarea');
    ta.value = text; ta.style.position='fixed'; ta.style.opacity='0';
    document.body.appendChild(ta); ta.select();
    document.execCommand('copy'); document.body.removeChild(ta);
    toast(okMsg||'Disalin!');
  }catch(e){ toast('Sila salin secara manual'); }
}

function renderCard(){
  var cardEl = $('#'+NS+'card');
  if(!cardEl) return;
  var pool = GREETINGS[activeCat] || [];
  if(!pool.length) return;
  var item = pick(pool);
  cardEl.classList.remove(NS+'arabic-card');
  if(activeCat === 'arabic' && typeof item === 'object'){
    cardEl.classList.add(NS+'arabic-card');
    cardEl.innerHTML = '<div><p>'+item.arabic+'</p><span class="'+NS+'rumi">'+item.rumi+'</span><span class="'+NS+'terjemah">'+item.terjemah+'</span></div>';
    lastText = item.arabic+'\n'+item.rumi+'\n'+item.terjemah;
    lastShareText = item.arabic+'\n\n'+item.rumi+'\n\n'+item.terjemah+'\n\nSumber: https://ilmualam.com/p/salam-jumaat-ucapan-maksud-hukum.html';
  } else {
    cardEl.innerHTML = '<p></p>';
    cardEl.querySelector('p').textContent = item;
    lastText = item;
    lastShareText = item + '\n\nSumber: https://ilmualam.com/p/salam-jumaat-ucapan-maksud-hukum.html';
  }
}

function initGenerator(){
  var catsEl = $('#'+NS+'cats');
  if(!catsEl) return;
  CAT_ORDER.forEach(function(key){
    if(!GREETINGS[key] || !GREETINGS[key].length) return;
    var b = document.createElement('button');
    b.type = 'button';
    b.className = NS+'chip';
    b.textContent = CAT_LABELS[key] || key;
    b.setAttribute('data-cat', key);
    b.setAttribute('aria-pressed', key === activeCat ? 'true' : 'false');
    b.style.touchAction = 'manipulation';
    catsEl.appendChild(b);
  });

  // Event delegation for INP: one listener for all chips + action buttons
  catsEl.addEventListener('click', function(e){
    var b = e.target.closest('button[data-cat]');
    if(!b) return;
    activeCat = b.getAttribute('data-cat');
    $all('button', catsEl).forEach(function(c){ c.setAttribute('aria-pressed', c===b ? 'true':'false'); });
    renderCard();
  });

  var toolEl = $('#'+NS+'tool');
  if(toolEl){
    toolEl.addEventListener('click', function(e){
      var t = e.target.closest('button');
      if(!t) return;
      if(t.id === NS+'generate') renderCard();
      if(t.id === NS+'copy') copyText(lastText, 'Ucapan disalin!');
      if(t.id === NS+'share'){
        if(!lastShareText){ toast('Jana ucapan dahulu'); return; }
        window.open('https://wa.me/?text='+encodeURIComponent(lastShareText), '_blank');
      }
    });
  }

  var searchEl = $('#'+NS+'search');
  if(searchEl){
    var timer = null;
    searchEl.addEventListener('input', function(){
      clearTimeout(timer);
      var q = searchEl.value.trim().toLowerCase();
      timer = setTimeout(function(){
        if(!q) return;
        for(var i=0;i<CAT_ORDER.length;i++){
          var key = CAT_ORDER[i];
          var pool = GREETINGS[key] || [];
          for(var j=0;j<pool.length;j++){
            var val = pool[j];
            var text = typeof val === 'object' ? (val.terjemah+' '+val.rumi) : val;
            if(text.toLowerCase().indexOf(q) !== -1){
              activeCat = key;
              $all('button', catsEl).forEach(function(c){ c.setAttribute('aria-pressed', c.getAttribute('data-cat')===key ? 'true':'false'); });
              var cardEl = $('#'+NS+'card');
              cardEl.classList.remove(NS+'arabic-card');
              if(typeof val === 'object'){
                cardEl.classList.add(NS+'arabic-card');
                cardEl.innerHTML = '<div><p>'+val.arabic+'</p><span class="'+NS+'rumi">'+val.rumi+'</span><span class="'+NS+'terjemah">'+val.terjemah+'</span></div>';
                lastText = val.arabic+'\n'+val.rumi+'\n'+val.terjemah;
              } else {
                cardEl.innerHTML = '<p></p>';
                cardEl.querySelector('p').textContent = val;
                lastText = val;
              }
              return;
            }
          }
        }
      }, 250);
    });
  }

  renderCard();
}

function initDoaBlocks(){
  var list = document.getElementById(NS+'doa-list');
  if(!list) return;
  list.addEventListener('click', function(e){
    var b = e.target.closest('button[data-copy-index]');
    if(!b) return;
    var i = +b.getAttribute('data-copy-index');
    var d = COPY_DATA[i];
    if(!d) return;
    if(b.hasAttribute('data-action-copy')){
      copyText(d.arabic+'\n'+d.rumi+'\n'+d.terjemah, 'Doa disalin!');
    } else if(b.hasAttribute('data-action-share')){
      window.open('https://wa.me/?text='+encodeURIComponent(d.whatsapp), '_blank');
    }
  });
}

function initFaqAccordion(){
  var wrap = document.getElementById(NS+'faq-list');
  if(!wrap) return;
  wrap.addEventListener('click', function(e){
    var btn = e.target.closest('.'+NS+'faq-q');
    if(!btn) return;
    var item = btn.closest('.'+NS+'faq-item');
    var panel = item.querySelector('.'+NS+'faq-a');
    var open = item.getAttribute('data-open') === 'true';
    item.setAttribute('data-open', open ? 'false' : 'true');
    btn.setAttribute('aria-expanded', open ? 'false' : 'true');
    panel.style.maxHeight = open ? '0px' : (panel.scrollHeight + 20) + 'px';
  });
}

setTimeout(function(){
  initGenerator();
  initDoaBlocks();
  initFaqAccordion();
}, 300);

window.ilmxSjGenerate = renderCard;
window.ilmxSjCopy = function(){ copyText(lastText, 'Ucapan disalin!'); };

})();
